    62  vcardvalue_kind vcardparameter_kind_value_kind(const vcardparameter_kind kind,
    63                                                 int *is_multivalued)
    64  {
    65      int i, num_params;
    66
    67      num_params = (int)(sizeof(parameter_map) / sizeof(parameter_map[0]));
    68      for (i = 0; i < num_params; i++) {
    69          if (parameter_map[i].kind == kind) {
    70              if (is_multivalued) {
    71                  *is_multivalued =
    72                      (parameter_map[i].flags & VCARD_PARAMETER_IS_MULTIVALUED);
    73              }
    74              return (parameter_map[i].value_kind);
    75          }
    76      }
    77
    78      return 0;
    79  }
    80
    81  bool vcardparameter_kind_is_valid(const vcardparameter_kind kind)
    82  {
    83      int i = 0;
    84      int num_params = (int)(sizeof(parameter_map) / sizeof(parameter_map[0]));
    85
    86      if (kind == VCARD_ANY_PARAMETER) {
    87          return false;
    88      }
    89
    90      num_params--;
    91      do {
    92          if (parameter_map[i].kind == kind) {
    93              return true;
    94          }
    95      } while (i++ < num_params);
    96
    97      return false;
    98  }
