   100  const char *vcardparameter_kind_to_string(vcardparameter_kind kind)
   101  {
   102      int i, num_params;
   103
   104      num_params = (int)(sizeof(parameter_map) / sizeof(parameter_map[0]));
   105      for (i = 0; i < num_params; i++) {
   106          if (parameter_map[i].kind == kind) {
   107              return parameter_map[i].name;
   108          }
   109      }
   110
   111      return 0;
   112  }
